"""Synthetic test fixtures.

Everything under ``synthetic/`` is generated by ``tooling/fixtures/make_fixtures.py``
from code and fixed seeds; nothing here may derive from a client document. Regenerate
with ``uv run python ../tooling/fixtures/make_fixtures.py`` from ``backEnd/``.

Import as ``from fixtures import fixture_path`` (``tests/`` is on ``sys.path`` through
``tests/conftest.py``, the same way ``dbtest_support`` is imported).
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

_ROOT = Path(__file__).resolve().parent


def fixtures_dir() -> Path:
    """The generated synthetic fixture directory (``backEnd/tests/fixtures/synthetic``)."""
    return _ROOT / "synthetic"


def fixture_path(*parts: str) -> Path:
    """Path of one synthetic fixture file; raises ``FileNotFoundError`` if it is missing."""
    path = fixtures_dir().joinpath(*parts)
    if not path.is_file():
        raise FileNotFoundError(
            f"synthetic fixture {'/'.join(parts)!r} not found; regenerate with "
            "`uv run python ../tooling/fixtures/make_fixtures.py` from backEnd/"
        )
    return path


def load_fixture_json(*parts: str) -> Any:
    """Parse a JSON fixture (golden files, labels, qrels, manifests)."""
    return json.loads(fixture_path(*parts).read_text(encoding="utf-8"))
